        complexity: { best: 'no carrier phase recovery and no phase ambiguity to resolve', avg: 'about 1 dB worse than coherent BPSK', worst: 'errors come in pairs, since each received symbol is used in two decisions', note: 'Pairing means the effective bit error rate is close to twice the symbol error rate.' },
