          feedback: { correct: 'Correct - shift the message up, then append the remainder as parity.', wrong: ['Correct - shift the message up, then append the remainder as parity.', 'Wrong - that is valid encoding but not systematic; the message is not visible.', 'Wrong - addition does not produce a multiple of g(x).', 'Wrong - the remainder alone discards the message entirely.'] },
